{
  "PROP-6a4369e9-inv-050": {
    "property_id": "PROP-6a4369e9-inv-050",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-050",
      "classification": "vulnerability",
      "code_path": "beacon_node/network/src/sync/range_sync/chain.rs::retry_partial_batch::L1102-1107",
      "proof_trace": "NoPeer error from retry_columns_by_range is caught at L1102 but only logged, not propagated. Function returns Ok(KeepChain) at L1107, leaving batch in Downloading state permanently. Batch never transitions to Failed or AwaitingDownload, preventing retry mechanisms from re-attempting the download.",
      "attack_scenario": "Attacker controls all custody peers for a column or network partitions the node from custody peers. Partial batch retry fails with NoPeer, error is silently swallowed, sync stalls permanently for that batch. Node cannot complete chain sync.",
      "checklist_id": "PROP-6a4369e9-inv-050"
    },
    "text": "Partial batch retry must not silently succeed when no eligible custody peers are available; NoPeer errors must trigger batch rescheduling or reset.",
    "assertion": "forall retry_partial_batch(failed_columns): retry_columns_by_range returns Err(NoPeer) => batch state transitions to failed/redownload, not KeepChain/Ok",
    "covers": "SG-006",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

